window.MOD = {"stats":{"fungi":63,"edible":36,"poisonous":27,"deadly":7,"classes":63},"fungi":[{"key":"blackmorel","cls":"geb_BlackMorel","name":"Black Morel","latin":"Morchella elata group","level":"Cook first","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A hollow, cone-shaped cap of olive-tan pits between dark ridges, joined straight onto a white, grainy stem. A prized edible, but it must be cooked: raw morels upset the stomach.","img":"assets/img/fungi/blackmorel.webp"},{"key":"whitemorel","cls":"geb_WhiteMorel","name":"White Morel","latin":"Morchella americana","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"An egg-shaped, honeycombed cap of pale ridges and grey-yellow pits on a thick white stem, hollow from top to bottom. Excellent eating once cooked; raw it causes stomach upset.","img":"assets/img/fungi/whitemorel.webp"},{"key":"lionsmane","cls":"geb_LionsMane","name":"Lion's Mane","latin":"Hericium erinaceus","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A white, rounded mass hanging cascades of soft, icicle-like spines, cut from a hardwood trunk. It has no poisonous look-alike; cooked it tastes like crab or lobster.","img":"assets/img/fungi/lionsmane.webp"},{"key":"puffball","cls":"geb_PuffBall","name":"Giant Puffball","latin":"Calvatia gigantea","level":"Edible","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A smooth, white, football-sized ball with no stem or gills. Edible while the flesh is firm and pure white all through; once it yellows it turns to spore dust.","img":"assets/img/fungi/puffball.webp"},{"key":"chanterelle","cls":"geb_Chanterelle","name":"Chanterelle","latin":"Cantharellus cibarius","level":"Edible","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"An egg-yolk yellow funnel with a wavy margin; underneath, blunt forked ridges (not true gills) run down the stem. Smells faintly of apricots. A choice edible; compare the orange, gilled and clustered jack-o'-lantern.","img":"assets/img/fungi/chanterelle.webp"},{"key":"chickenofthewoods","cls":"geb_ChickenOfTheWoods","name":"Chicken of the Woods","latin":"Laetiporus sulphureus","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"Overlapping shelves, bright orange above with sulphur-yellow pores below, cut from a tree. The tender edges taste like chicken once cooked; raw it can upset the stomach.","img":"assets/img/fungi/chickenofthewoods.webp"},{"key":"henofthewoods","cls":"geb_HenOfTheWoods","name":"Hen of the Woods","latin":"Grifola frondosa","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A big rosette of overlapping grey-brown, spoon-shaped fronds on branching white stalks, found at the foot of oaks. A choice edible with no dangerous look-alike.","img":"assets/img/fungi/henofthewoods.webp"},{"key":"shaggymane","cls":"geb_ShaggyMane","name":"Shaggy Mane","latin":"Coprinus comatus","level":"Edible","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A tall white cylinder of a cap covered in shaggy, brown-tipped scales, with a loose ring low on the stem. Good to eat while white; within hours of picking it dissolves into black ink.","img":"assets/img/fungi/shaggymane.webp"},{"key":"hedgehog","cls":"geb_HedgehogMushroom","name":"Hedgehog Mushroom","latin":"Hydnum repandum","level":"Edible","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A lumpy, pale apricot cap with small soft spines underneath instead of gills, on a stout, often off-centre stem. Nothing poisonous looks like it; firm and sweet when cooked.","img":"assets/img/fungi/hedgehog.webp"},{"key":"honeymushroom","cls":"geb_HoneyMushroom","name":"Honey Mushroom","latin":"Armillaria mellea","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A tuft of honey-coloured caps, darker and finely scaly at the centre, with whitish gills and a cottony ring on each stem, growing from stumps. Edible only well cooked; raw it causes food poisoning.","img":"assets/img/fungi/honeymushroom.webp"},{"key":"woodblewit","cls":"geb_WoodBlewit","name":"Wood Blewit","latin":"Lepista nuda","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A smooth tan cap flushed lilac, crowded violet gills and a stout lilac stem with a swollen base. Edible cooked; raw it disagrees with most stomachs. Beware rusty-gilled webcaps.","img":"assets/img/fungi/woodblewit.webp"},{"key":"lobstermushroom","cls":"geb_LobsterMushroom","name":"Lobster Mushroom","latin":"Hypomyces lactifluorum","level":"Edible","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A mould that turns a milk-cap into a contorted, lobster-red funnel with a pimpled crust and dense white flesh. Firm, seafood-flavoured and edible cooked.","img":"assets/img/fungi/lobstermushroom.webp"},{"key":"indigomilkcap","cls":"geb_IndigoMilkCap","name":"Indigo Milk Cap","latin":"Lactarius indigo","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A cap of concentric indigo-blue zones, sunk in the middle, with crowded blue gills on a short blue stem. Cut, it bleeds blue milk and slowly bruises green. Edible cooked; nothing else in the woods is this blue.","img":"assets/img/fungi/indigomilkcap.webp"},{"key":"winecap","cls":"geb_WineCap","name":"Wine Cap","latin":"Stropharia rugosoannulata","level":"Cook first","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A big burgundy-red cap fading to tan, grey-violet gills that darken with dark spores, and a thick white stem with a ring split like a cogwheel. Grows in wood chips and mulch. Edible cooked.","img":"assets/img/fungi/winecap.webp"},{"key":"velvetfoot","cls":"geb_VelvetFoot","name":"Velvet Foot","latin":"Flammulina velutipes","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"Tufts of sticky, orange-brown caps with pale gills on stems that turn dark and velvety toward the base, fruiting on dead elm and willow even in winter frost. Edible cooked. Compare the deadly funeral bell, which has a ring and rusty gills.","img":"assets/img/fungi/velvetfoot.webp"},{"key":"beefsteak","cls":"geb_BeefsteakFungus","name":"Beefsteak Fungus","latin":"Fistulina hepatica","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A moist, liver-red tongue growing from oak and chestnut trunks, with cream pores beneath that bruise red. Cut, the flesh is marbled like raw steak and weeps red juice. Edible, though sour; best cooked.","img":"assets/img/fungi/beefsteak.webp"},{"key":"cauliflower","cls":"geb_CauliflowerMushroom","name":"Cauliflower Mushroom","latin":"Sparassis spathulata","level":"Edible","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A bouquet of flat, wavy, cream lobes like a head of egg noodles, at the foot of pines and oaks. A choice edible with no dangerous look-alike; wash the grit out of its folds.","img":"assets/img/fungi/cauliflower.webp"},{"key":"gempuffball","cls":"geb_GemPuffball","name":"Gem-studded Puffball","latin":"Lycoperdon perlatum","level":"Edible","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A small, pear-shaped white puffball studded with cone-shaped warts that rub off and leave a net of scars. Edible while pure white and firm all through; slice it to make sure it is no young amanita.","img":"assets/img/fungi/gempuffball.webp"},{"key":"baybolete","cls":"geb_BayBolete","name":"Bay Bolete","latin":"Imleria badia","level":"Cook first","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A smooth, chestnut-brown cushion of a cap with cream-yellow pores (not gills) beneath that bruise blue-green, on a firm, streaked brown stem, under pines. A good edible; cook it. Compare the devil's bolete's red pores and netted stem.","img":"assets/img/fungi/baybolete.webp"},{"key":"birchbolete","cls":"geb_OrangeBirchBolete","name":"Orange Birch Bolete","latin":"Leccinum versipelle","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A bright orange cap whose skin overhangs the margin, grey-cream pores and a tall white stem covered in black woolly scales, under birches. Edible only well cooked; raw or undercooked it makes people sick.","img":"assets/img/fungi/birchbolete.webp"},{"key":"oldmanofthewoods","cls":"geb_OldManOfTheWoods","name":"Old Man of the Woods","latin":"Strobilomyces strobilaceus","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A shaggy bolete covered in soft, grey-black woolly scales over white, with greyish pores that redden then blacken when bruised and a shaggy stem. Strange to look at, but edible cooked.","img":"assets/img/fungi/oldmanofthewoods.webp"},{"key":"amethystdeceiver","cls":"geb_AmethystDeceiver","name":"Amethyst Deceiver","latin":"Laccaria amethystina","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"Small, vivid violet caps, thick, widely spaced purple gills and tough, fibrous purple stems in leaf litter. Edible. It fades to buff as it dries out, which is how it deceives.","img":"assets/img/fungi/amethystdeceiver.webp"},{"key":"fairyring","cls":"geb_FairyRingChampignon","name":"Fairy Ring Champignon","latin":"Marasmius oreades","level":"Edible","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"Tan, bell-shaped caps with a central knob, widely spaced cream gills and tough, thin stems, growing in rings in short grass. Edible and good dried, but the poisonous ivory funnel grows in the same rings: check every one.","img":"assets/img/fungi/fairyring.webp"},{"key":"halffreemorel","cls":"geb_HalfFreeMorel","name":"Half-free Morel","latin":"Morchella punctipes","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A small, pitted, dark-ridged morel cap whose lower half hangs free like a skirt over a long, pale, hollow stem. Edible cooked, like other morels. Compare the early false morel, whose cap hangs free right up to the top.","img":"assets/img/fungi/halffreemorel.webp"},{"key":"deathcap","cls":"geb_DeathCap","name":"Death Cap","latin":"Amanita phalloides","level":"Deadly","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"An olive-green cap streaked with fine dark fibres, crowded white gills, a white skirt on the stem and a white sac-like cup round the bulbous base. Deadly. Cooking and drying do not destroy its toxins, which destroy the liver.","img":"assets/img/fungi/deathcap.webp"},{"key":"destroyingangel","cls":"geb_DestroyingAngel","name":"Destroying Angel","latin":"Amanita bisporigera","level":"Deadly","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"Pure white all over, with a smooth satin cap, free white gills, a thin skirt on a slender stem and a sac-like cup at the base, often hidden in the soil. Deadly, even after cooking.","img":"assets/img/fungi/destroyingangel.webp"},{"key":"falsemorel","cls":"geb_FalseMorel","name":"False Morel","latin":"Gyromitra esculenta","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A reddish-brown cap folded like a brain rather than pitted like a honeycomb, on a stout, chambered stem. Poisonous: it causes vomiting and liver damage, and boiling only partly helps.","img":"assets/img/fungi/falsemorel.webp"},{"key":"jackolantern","cls":"geb_JackOLantern","name":"Jack-o'-Lantern","latin":"Omphalotus illudens","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"Clustered bright orange caps on fused stems, with sharp, true gills running down the stem. Its gills glow faintly in the dark. Poisonous: severe vomiting. Often mistaken for chanterelles.","img":"assets/img/fungi/jackolantern.webp"},{"key":"earthball","cls":"geb_Earthball","name":"Common Earthball","latin":"Scleroderma citrinum","level":"Poisonous","edible":false,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A hard, ochre-yellow ball with a thick, warty, cracked skin and a short rooting base. Cut open it is purple-black inside, not white like a puffball. Poisonous: vomiting and cramps.","img":"assets/img/fungi/earthball.webp"},{"key":"sulphurtuft","cls":"geb_SulphurTuft","name":"Sulphur Tuft","latin":"Hypholoma fasciculare","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"Dense tufts of small sulphur-yellow caps with tawny centres and greenish-yellow gills turning purple-brown, on stumps. Very bitter and poisonous: vomiting and diarrhoea. Not a honey mushroom.","img":"assets/img/fungi/sulphurtuft.webp"},{"key":"deadlywebcap","cls":"geb_DeadlyWebcap","name":"Deadly Webcap","latin":"Cortinarius rubellus","level":"Deadly","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A fox-red, silky cap with a pointed hump, rusty-brown gills and faint yellow bands on the stem. Deadly. There are no symptoms at first; days later the kidneys fail. Cooking does not help.","img":"assets/img/fungi/deadlywebcap.webp"},{"key":"greensporedparasol","cls":"geb_GreenSporedParasol","name":"Green-spored Parasol","latin":"Chlorophyllum molybdites","level":"Poisonous","edible":false,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A large white cap with a brown centre breaking into scattered scales, a thick ring and gills that turn grey-green with age. Poisonous: violent vomiting and diarrhoea. Easily mistaken for an edible parasol.","img":"assets/img/fungi/greensporedparasol.webp"},{"key":"panthercap","cls":"geb_PantherCap","name":"Panther Cap","latin":"Amanita pantherina","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A brown cap scattered with pure white warts, a finely grooved margin, white gills, a white ring and a rimmed bulb at the base. Poisonous: vomiting, delirium and seizures within hours. It is the fly agaric's more dangerous brown cousin.","img":"assets/img/fungi/panthercap.webp"},{"key":"funeralbell","cls":"geb_FuneralBell","name":"Funeral Bell","latin":"Galerina marginata","level":"Deadly","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"Tufts of small, honey-brown caps with rusty gills and a thin brown ring on the stem, growing on rotting wood. Deadly: the same liver-destroying toxins as the death cap, and cooking does not help. Easily picked by mistake with honey mushrooms or velvet foot.","img":"assets/img/fungi/funeralbell.webp"},{"key":"emeticrussula","cls":"geb_EmeticRussula","name":"The Sickener","latin":"Russula emetica","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A bright scarlet cap with brittle, pure white gills and a white stem, in damp pine woods and moss. Tastes hot as pepper. Poisonous: vomiting and diarrhoea, as its name promises.","img":"assets/img/fungi/emeticrussula.webp"},{"key":"yellowstainer","cls":"geb_YellowStainer","name":"Yellow Stainer","latin":"Agaricus xanthodermus","level":"Poisonous","edible":false,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"Looks like a field mushroom, with a white cap, pink-to-chocolate gills and a thick ring, but the base of its stem turns chrome yellow when cut and it smells of ink. Poisonous: vomiting, cramps and sweating.","img":"assets/img/fungi/yellowstainer.webp"},{"key":"ivoryfunnel","cls":"geb_IvoryFunnel","name":"Ivory Funnel","latin":"Clitocybe rivulosa","level":"Poisonous","edible":false,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"Small, flat-to-funnelled caps with a frosty white bloom and white gills running down the stem, in rings on lawns and grassland. Poisonous: sweating, drooling, tears and a failing pulse within the hour.","img":"assets/img/fungi/ivoryfunnel.webp"},{"key":"brownrollrim","cls":"geb_BrownRollrim","name":"Brown Roll-rim","latin":"Paxillus involutus","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A brown, felty funnel with a tightly rolled-under margin and soft yellow-olive gills that bruise brown, under birches. Once eaten as a staple; the poison builds up and a later meal can destroy the blood. Raw or cooked, leave it.","img":"assets/img/fungi/brownrollrim.webp"},{"key":"devilsbolete","cls":"geb_DevilsBolete","name":"Devil's Bolete","latin":"Rubroboletus satanas","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A heavy bolete with a chalky, pale grey cap, blood-red pores that bruise blue and a swollen stem netted red over yellow. Smells foul when old. Poisonous: violent vomiting. Compare the bay bolete's cream pores and plain stem.","img":"assets/img/fungi/devilsbolete.webp"},{"key":"deadlydapperling","cls":"geb_DeadlyDapperling","name":"Deadly Dapperling","latin":"Lepiota brunneoincarnata","level":"Deadly","edible":false,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A small white cap covered in rings of pinkish-brown scales, darkest at the centre, with free white gills and a stem banded with the same scales. Deadly: the death cap's liver toxins, and cooking does not help.","img":"assets/img/fungi/deadlydapperling.webp"},{"key":"deadlyfibrecap","cls":"geb_DeadlyFibrecap","name":"Deadly Fibrecap","latin":"Inocybe erubescens","level":"Deadly","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A cream, conical cap of silky radial fibres that splits at the margin and bruises brick-red, with clay-brown gills, in spring woods. Deadly: its muscarine brings drenching sweat, tears, a slowing heart and collapse within the hour.","img":"assets/img/fungi/deadlyfibrecap.webp"},{"key":"lividpinkgill","cls":"geb_LividPinkgill","name":"Livid Pinkgill","latin":"Entoloma sinuatum","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A large, satiny grey-white cap with a wavy margin and gills that start yellowish and turn salmon-pink, on a stout white stem. Smells of meal. Poisonous: days of vomiting and diarrhoea. Easily taken for an edible field mushroom.","img":"assets/img/fungi/lividpinkgill.webp"},{"key":"falsedeathcap","cls":"geb_FalseDeathCap","name":"False Death Cap","latin":"Amanita citrina","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A pale lemon-yellow cap scattered with buff veil patches, white gills, a drooping ring and a big round bulb with a sharp rim. Smells of raw potato. Mildly poisonous, and far too like the death cap to risk.","img":"assets/img/fungi/falsedeathcap.webp"},{"key":"earlyfalsemorel","cls":"geb_EarlyFalseMorel","name":"Early False Morel","latin":"Verpa bohemica","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A wrinkled brown thimble of a cap that hangs completely free from the top of a long, pale stem stuffed with cotton, in spring. Poisonous, worse raw: vomiting, cramps and loss of coordination. Slice it: a true morel's cap is fused to its stem.","img":"assets/img/fungi/earlyfalsemorel.webp"},{"key":"americancaesar","cls":"geb_AmericanCaesar","name":"American Caesar","latin":"Amanita jacksonii","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A glowing orange-red cap with a lined margin, yellow gills, a yellow stem with an orange skirt, standing in a thick white cup. An edible amanita, prized since Roman times. Learn it well: everything else in its family is a gamble.","img":"assets/img/fungi/americancaesar.webp"},{"key":"horsemushroom","cls":"geb_HorseMushroom","name":"Horse Mushroom","latin":"Agaricus arvensis","level":"Edible","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A big, smooth white cap that yellows where touched, greyish-pink gills turning chocolate brown, and a large two-layered ring with a cogwheel underside. Smells of aniseed. Excellent eating; the yellow stainer is its look-alike and smells of ink instead.","img":"assets/img/fungi/horsemushroom.webp"},{"key":"stgeorges","cls":"geb_StGeorgesMushroom","name":"St George's Mushroom","latin":"Calocybe gambosa","level":"Edible","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A thick, creamy-white cap with a rolled-in margin, very crowded white gills and a stout stem, growing in rings in spring grass. Smells of fresh meal. A choice edible; the deadly fibrecap shares its season.","img":"assets/img/fungi/stgeorges.webp"},{"key":"dryadssaddle","cls":"geb_DryadsSaddle","name":"Dryad's Saddle","latin":"Cerioporus squamosus","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A broad, saddle-shaped bracket on dying hardwoods, cream covered in rings of dark, feathery scales, with big angular pores underneath and a short black stub of a stem. Smells of watermelon rind. Eat it young and tender, well cooked.","img":"assets/img/fungi/dryadssaddle.webp"},{"key":"bearshead","cls":"geb_BearsHeadTooth","name":"Bear's Head Tooth","latin":"Hericium americanum","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A branching white mass dripping with long icicle spines in tiers, on fallen hardwood logs. Like its cousin the lion's mane, it has no poisonous look-alike, and it cooks like seafood.","img":"assets/img/fungi/bearshead.webp"},{"key":"matsutake","cls":"geb_Matsutake","name":"Matsutake","latin":"Tricholoma murrillianum","level":"Edible","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A firm white cap streaked with brown fibres, white gills that spot rusty, and a thick stem with a cottony ring and a brown, scaly sheath below it, under pines. Smells of cinnamon and old socks. One of the most prized mushrooms in the world.","img":"assets/img/fungi/matsutake.webp"},{"key":"shaggyparasol","cls":"geb_ShaggyParasol","name":"Shaggy Parasol","latin":"Chlorophyllum rhacodes","level":"Cook first","edible":true,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A brown-capped dome that opens into a white parasol shaggy with coarse brown scales, on a smooth stem with a thick, movable ring and an abrupt bulb. Its flesh reddens when cut. Edible cooked; raw it upsets the stomach. Check the gills stay white: the green-spored parasol's turn grey-green.","img":"assets/img/fungi/shaggyparasol.webp"},{"key":"witchsbutter","cls":"geb_WitchsButter","name":"Witch's Butter","latin":"Tremella mesenterica","level":"Edible","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A bright yellow-orange jelly folded like a little brain, on dead branches after rain. It shrivels to an orange crust in dry weather and swells again when wet. Edible, but almost tasteless: a thickener for soup.","img":"assets/img/fungi/witchsbutter.webp"},{"key":"turkeytail","cls":"geb_TurkeyTail","name":"Turkey Tail","latin":"Trametes versicolor","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"Overlapping tiers of thin, velvety fans banded brown, blue-grey and cream with a pale wavy margin and tiny white pores beneath. Far too tough to eat; boiled, it makes a bitter tea that warms and rehydrates.","img":"assets/img/fungi/turkeytail.webp"},{"key":"hemlockreishi","cls":"geb_HemlockReishi","name":"Hemlock Reishi","latin":"Ganoderma tsugae","level":"Cook first","edible":true,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A kidney-shaped shelf with a lacquered, mahogany-red top fading to a cream margin, and white pores beneath, on dead hemlocks. Woody and bitter; boiled, it makes a dark tea people have drunk for centuries.","img":"assets/img/fungi/hemlockreishi.webp"},{"key":"chaga","cls":"geb_Chaga","name":"Chaga","latin":"Inonotus obliquus","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A black, deeply cracked growth like burnt charcoal on living birch, with rusty-orange, corky flesh inside. Not something to chew: break off a piece and boil it for an earthy tea.","img":"assets/img/fungi/chaga.webp"},{"key":"crowntippedcoral","cls":"geb_CrownTippedCoral","name":"Crown-tipped Coral","latin":"Artomyces pyxidatus","level":"Cook first","edible":true,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A creamy-yellow candelabra of branches that fork in whorls, every tip ending in a tiny crown, on rotting logs. Edible cooked, with a peppery bite; raw it can upset the stomach.","img":"assets/img/fungi/crowntippedcoral.webp"},{"key":"yellowknight","cls":"geb_YellowKnight","name":"Yellow Knight","latin":"Tricholoma equestre","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A sulphur-yellow cap with a darker, finely scaly centre, bright yellow gills and stem, often half buried in sandy soil under pines. Once a famous edible; eaten meal after meal, its poison wastes the muscles and strains the heart.","img":"assets/img/fungi/yellowknight.webp"},{"key":"poisonpie","cls":"geb_PoisonPie","name":"Poison Pie","latin":"Hebeloma crustuliniforme","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A sticky, pale buff cap like a pastry crust, darker in the middle, clay-brown gills that weep watery beads, and a white stem frosted at the top. Smells of radish. Poisonous: hours of vomiting.","img":"assets/img/fungi/poisonpie.webp"},{"key":"cloudedagaric","cls":"geb_CloudedAgaric","name":"Clouded Agaric","latin":"Clitocybe nebularis","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A big, cloudy grey cap with a pale bloom, crowded cream gills running a little down the stem, often in rings among fallen needles. Smells sickly sweet. Upsets most stomachs badly; best left alone.","img":"assets/img/fungi/cloudedagaric.webp"},{"key":"bitterbolete","cls":"geb_BitterBolete","name":"Bitter Bolete","latin":"Tylopilus felleus","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A handsome tan bolete with pinkish pores and a dark brown net on its stem. Not poisonous, but so bitter that one in the pan ruins the meal and brings it back up. Mistaken for a penny bun, whose net is white.","img":"assets/img/fungi/bitterbolete.webp"},{"key":"conocybefilaris","cls":"geb_ConocybeFilaris","name":"Ringed Conecap","latin":"Pholiotina rugosa","level":"Deadly","edible":false,"habitat":"Meadows and rich soil","event":"TrajectoryHumus","desc":"A tiny, rusty-brown conical cap on a slender stem with a thin membranous ring, in mulch and lawns. Easy to overlook, easy to take for something harmless. Deadly: the same liver toxins as the death cap.","img":"assets/img/fungi/conocybefilaris.webp"},{"key":"stinkhorn","cls":"geb_Stinkhorn","name":"Stinkhorn","latin":"Phallus ravenelii","level":"Poisonous","edible":false,"habitat":"Broadleaf woods","event":"TrajectoryDeciduous","desc":"A spongy white stalk rising from a soft white egg, capped with a dark olive slime that smells of rotting meat and draws flies from yards away. Not deadly, but eating one brings it straight back up.","img":"assets/img/fungi/stinkhorn.webp"},{"key":"scalyvase","cls":"geb_ScalyVase","name":"Scaly Vase Chanterelle","latin":"Turbinellus floccosus","level":"Poisonous","edible":false,"habitat":"Conifer woods","event":"TrajectoryConiferous","desc":"A tall orange vase, its hollow top rough with upturned scales, the outside ribbed with cream, blunt ridges. Related to chanterelles, but it brings on vomiting and cramps for most who eat it.","img":"assets/img/fungi/scalyvase.webp"}],"classes":[["geb_AmericanCaesar","Edible fungus","American Caesar"],["geb_AmethystDeceiver","Edible fungus","Amethyst Deceiver"],["geb_BayBolete","Edible fungus","Bay Bolete"],["geb_BearsHeadTooth","Edible fungus","Bear's Head Tooth"],["geb_BeefsteakFungus","Edible fungus","Beefsteak Fungus"],["geb_BlackMorel","Edible fungus","Black Morel"],["geb_CauliflowerMushroom","Edible fungus","Cauliflower Mushroom"],["geb_Chaga","Edible fungus","Chaga"],["geb_Chanterelle","Edible fungus","Chanterelle"],["geb_ChickenOfTheWoods","Edible fungus","Chicken of the Woods"],["geb_CrownTippedCoral","Edible fungus","Crown-tipped Coral"],["geb_DryadsSaddle","Edible fungus","Dryad's Saddle"],["geb_FairyRingChampignon","Edible fungus","Fairy Ring Champignon"],["geb_GemPuffball","Edible fungus","Gem-studded Puffball"],["geb_PuffBall","Edible fungus","Giant Puffball"],["geb_HalfFreeMorel","Edible fungus","Half-free Morel"],["geb_HedgehogMushroom","Edible fungus","Hedgehog Mushroom"],["geb_HemlockReishi","Edible fungus","Hemlock Reishi"],["geb_HenOfTheWoods","Edible fungus","Hen of the Woods"],["geb_HoneyMushroom","Edible fungus","Honey Mushroom"],["geb_HorseMushroom","Edible fungus","Horse Mushroom"],["geb_IndigoMilkCap","Edible fungus","Indigo Milk Cap"],["geb_LionsMane","Edible fungus","Lion's Mane"],["geb_LobsterMushroom","Edible fungus","Lobster Mushroom"],["geb_Matsutake","Edible fungus","Matsutake"],["geb_OldManOfTheWoods","Edible fungus","Old Man of the Woods"],["geb_OrangeBirchBolete","Edible fungus","Orange Birch Bolete"],["geb_ShaggyMane","Edible fungus","Shaggy Mane"],["geb_ShaggyParasol","Edible fungus","Shaggy Parasol"],["geb_StGeorgesMushroom","Edible fungus","St George's Mushroom"],["geb_TurkeyTail","Edible fungus","Turkey Tail"],["geb_VelvetFoot","Edible fungus","Velvet Foot"],["geb_WhiteMorel","Edible fungus","White Morel"],["geb_WineCap","Edible fungus","Wine Cap"],["geb_WitchsButter","Edible fungus","Witch's Butter"],["geb_WoodBlewit","Edible fungus","Wood Blewit"],["geb_BitterBolete","Poisonous fungus","Bitter Bolete"],["geb_BrownRollrim","Poisonous fungus","Brown Roll-rim"],["geb_CloudedAgaric","Poisonous fungus","Clouded Agaric"],["geb_Earthball","Poisonous fungus","Common Earthball"],["geb_DeadlyDapperling","Poisonous fungus","Deadly Dapperling"],["geb_DeadlyFibrecap","Poisonous fungus","Deadly Fibrecap"],["geb_DeadlyWebcap","Poisonous fungus","Deadly Webcap"],["geb_DeathCap","Poisonous fungus","Death Cap"],["geb_DestroyingAngel","Poisonous fungus","Destroying Angel"],["geb_DevilsBolete","Poisonous fungus","Devil's Bolete"],["geb_EarlyFalseMorel","Poisonous fungus","Early False Morel"],["geb_FalseDeathCap","Poisonous fungus","False Death Cap"],["geb_FalseMorel","Poisonous fungus","False Morel"],["geb_FuneralBell","Poisonous fungus","Funeral Bell"],["geb_GreenSporedParasol","Poisonous fungus","Green-spored Parasol"],["geb_IvoryFunnel","Poisonous fungus","Ivory Funnel"],["geb_JackOLantern","Poisonous fungus","Jack-o'-Lantern"],["geb_LividPinkgill","Poisonous fungus","Livid Pinkgill"],["geb_PantherCap","Poisonous fungus","Panther Cap"],["geb_PoisonPie","Poisonous fungus","Poison Pie"],["geb_ConocybeFilaris","Poisonous fungus","Ringed Conecap"],["geb_ScalyVase","Poisonous fungus","Scaly Vase Chanterelle"],["geb_Stinkhorn","Poisonous fungus","Stinkhorn"],["geb_SulphurTuft","Poisonous fungus","Sulphur Tuft"],["geb_EmeticRussula","Poisonous fungus","The Sickener"],["geb_YellowKnight","Poisonous fungus","Yellow Knight"],["geb_YellowStainer","Poisonous fungus","Yellow Stainer"]]};
